add(nr=19, id="10636706349322", orig_titel="Bumper Plates COLOR 51mm 5-25kg",
 fakta="Bumper Plates COLOR 51mm 5-25kg. Bumper Plates COLOR är alla slitstarka viktskivor i olika färg anpassade för skivstänger med diameter på 50mm. Det som generellt sett utmärker bumpervikter är att alla viktskivor har samma diameter vilket vid träning gör att alla viktskivor lastade på skivstången gemensamt tar smällen när du droppar vikten i golvet. Dessa viktskivor är utformade för att klara av den höga belastning som lätt uppstår vid utförande av tex olympiska lyft. Givetvis fungerar de även väldigt bra till traditionell styrketräning också så som knäböj, marklyft, bänkpress och axelpress. Obs! Det som är speciellt med dessa viktskivor är att vikten sitter centrerat i mitten av viktskivan och inte jämt fördelat över hela skivan. Den här produkten finns att se på plats i vårt showroom. Finns i följande vikter: 5kg, 10kg, 15kg, 20kg och 25kg. Material: Järn med gummibeläggning. Håldiameter: 51mm. Säljs en och en. Dimensioner: 5kg: Diameter - 25cm, Diameter järnstjärna - 12cm, Tjocklek - 3,4cm. 10kg: Diameter - 45cm, Diameter järnstjärna - 12cm, Tjocklek - 3,6cm. 15kg: Diameter - 45cm, Diameter järnstjärna - 14cm, Tjocklek - 4cm. 20kg: Diameter - 45cm, Diameter järnstjärna - 14cm, Tjocklek - 5cm. 25kg: Diameter - 45cm, Diameter järnstjärna - 14cm, Tjocklek - 6cm. Varianter: Svart - 5kg, Grön - 10kg, Gul - 15kg, Blå - 20kg, Röd - 25kg. Märke Gorilla Sports Norden",
 titel="Viktskivor Bumper Color 51 mm, 5–25 kg",
 seo_title="Viktskivor Bumper Color 51 mm, 5–25 kg",
 meta="Bumperskivor i järn med gummibeläggning för skivstänger med 50 mm diameter. Fem vikter, 5–25 kg, i olika färger. Håldiameter 51 mm. Säljs en och en.",
 intro="Bumper Color är viktskivor i järn med gummibeläggning för skivstänger med 50 mm diameter. De finns i fem vikter, 5–25 kg, i olika färger och säljs en och en.",
 passar=["Lyft där vikten släpps i golvet, till exempel olympiska lyft","Knäböj, marklyft, bänkpress och axelpress","Dig som har en skivstång med 50 mm diameter"],
 spec=["25 kg: diameter 45 cm, diameter järnstjärna 14 cm, tjocklek 6 cm","20 kg: diameter 45 cm, diameter järnstjärna 14 cm, tjocklek 5 cm","15 kg: diameter 45 cm, diameter järnstjärna 14 cm, tjocklek 4 cm","10 kg: diameter 45 cm, diameter järnstjärna 12 cm, tjocklek 3,6 cm","5 kg: diameter 25 cm, diameter järnstjärna 12 cm, tjocklek 3,4 cm","Vikter och färger: svart 5 kg, grön 10 kg, gul 15 kg, blå 20 kg, röd 25 kg","Material: järn med gummibeläggning","Håldiameter: 51 mm","Säljs en och en"],
 faq=[("Hur är vikten fördelad?","Vikten sitter centrerat i mitten av skivan och inte jämnt fördelad över hela skivan, till skillnad från en vanlig viktskiva.")], marke=None,
 motivering="Fakta ur källan. Showroom-raden (Gorillas adress) och \"slitstarka\" utelämnas.",
 att_bekrafta=["Källan säger att alla skivor har samma diameter, men måtten visar 25 cm för 5 kg och 45 cm för övriga. Texten påstår inte samma diameter.","Showroom-uppgiften hör till Gorilla Sports och är bortagen från BOS-texten."])

