add(nr=21, id="10636616040714", orig_titel="Hip Glute Band Women's Health Paket",
 fakta="Hip Glute Band Women's Health Paket. Perfekta band om du vill träna hemma, eller på gymmet. Höftbanden säljs i ett set om 3 och en bärpåse medföljer. Träna ben effektivt med dessa höftband som kommer i tre olika motståndsnivåer. Turkos/Mintgrön – Lätt, rosa – Medium och grå – Tung. Material: 65% polyester, 35% bomull. Gummerad insida för bättre grepp. Förvaringspåse medföljer. Omkrets: 76cm. Bredd: 8cm. Ett smidigt och effektivt redskap för att maximera dina träningspass. Märke Gorilla Sports Norden, taggar glute band, womens health",
 titel="Höftband Hip Glute Band Women's Health, set med 3 band",
 seo_title="Höftband Hip Glute Band, set med 3 band",
 meta="Hip Glute Band Women's Health är tre höftband i tyg med gummerad insida, i tre motståndsnivåer: lätt, medium och tung. Omkrets 76 cm, bredd 8 cm, med påse.",
 intro="Hip Glute Band Women's Health är ett set med tre höftband i tre motståndsnivåer, avsedda för träning hemma eller på gymmet. En bärpåse medföljer.",
 passar=["Dig som tränar ben hemma eller på gymmet","Dig som vill kunna välja mellan tre motståndsnivåer"],
 spec=["Motståndsnivåer: turkos/mintgrön lätt, rosa medium, grå tung","Material: 65 % polyester, 35 % bomull","Förvaring: bärpåse medföljer","Gummerad insida för bättre grepp","Omkrets: 76 cm","Bredd: 8 cm","Set: 3 band"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Perfekta\", \"effektivt\" och \"maximera\" utelämnas.",
 att_bekrafta=["\"Women's Health\" i namnet är ett varumärkes- eller produktnamn som inte förklaras i källan. Texten behåller det som namn.","Vilken färg som är lätt, medium och tung följer källans uppräkning."])

add(nr=22, id="10472265154826", orig_titel="Träningsmatta TUNTURI NBR, Petrol Blue",
 fakta="Träningsmatta TUNTURI NBR, Petrol Blue. Tunturi Fitnessmat NBR erbjuder utmärkt komfort under träningen, tillverkad av mjukt och slitstarkt NBR-material. Mattan har en tjocklek på 15 mm, vilket ger tillräcklig dämpning och skydd under golvövningar. Den blå designen är portabel tack vare den medföljande bärväskan, vilket gör den enkel att transportera. Övrig information: Material: NBR (Nitrilbutadengummi). NBR (NBR nitrilgummi) Finns även i andra färger. Levereras med: bärväska. Nylon (NBR): Yoga, Pilates och allmän träning. Mått: 180 x 60 cm. Märke Tunturi, typ Yogamattor, SKU 14TUSFU323",
 titel="Träningsmatta Tunturi NBR, 15 mm, petrolblå",
 seo_title="Träningsmatta Tunturi NBR, 15 mm",
 meta="Tunturi NBR är en träningsmatta i NBR-gummi, 15 mm tjock och 180 x 60 cm, för yoga, pilates och allmän träning. Bärväska medföljer. Finns i fler färger.",
 intro="Tunturi NBR är en träningsmatta i NBR-gummi, 15 mm tjock och 180 x 60 cm, för golvövningar, yoga, pilates och allmän träning. En bärväska medföljer.",
 passar=["Yoga, pilates och allmän träning","Golvövningar","Dig som vill kunna bära med mattan (bärväska medföljer)"],
 spec=["Mått: 180 x 60 cm","Tjocklek: 15 mm","Levereras med: bärväska","Material: NBR (nitrilbutadiengummi)","Färg: petrolblå, finns även i andra färger"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Utmärkt komfort\" och \"tillräcklig dämpning och skydd\" utelämnas.",
 att_bekrafta=["Raden \"Nylon (NBR): Yoga, Pilates...\" i källan är oklar. Texten tolkar den som användningsområden.","Vikt saknas."])

add(nr=23, id="10462775771402", orig_titel="Yogamatta Tunturi Yogamat 8mm, Rose Gold",
 fakta="Yogamatta Tunturi Yogamat 8mm, Rose Gold. Med Tunturis extra tjocka 8 mm matta har du en yogamatta, träningsmatta och övningsmatta i ett. Extra tjock 8 mm matta för maximal komfort under träning. Perfekt för yoga-, fitness- och pilatesklasser. Halkfri, lätt att rengöra och biologiskt nedbrytbar. Levereras med en praktisk bärväska och gratis app. Tunturi Yoga Mat 8 mm är idealisk för alla former av yoga där du utför många poser liggande eller sittande, som yin yoga, yoga nidra och meditation. Mattan är tjockare än vanliga yogamattor (3-4 mm). Mattan är också mycket lämplig för andra träningsformer som fitness och pilates. Yogamattan är tillverkad av 100 % TPE: en kombination av gummi och plast. Mattan är extra mjuk, halkfri och motståndskraftig mot svett, lukt och bakterier. Du kan enkelt rengöra mattan med lite rengöringsmedel. Träningsmattan finns i 7 färger och levereras med en bärväska. Om du använder en matta första gången: ta ut den ur förpackningen, rulla ut den på golvet och låt den vila i några timmar. Om Tunturi: rötter i Finland, två bröder grundade en cykelbutik 1922. Mer information: Vikt: 950 gr. Material: TPE. Färg: Roséguld. Märke Tunturi. Varianter Default Title, tagg På beställning",
 titel="Yogamatta Tunturi 8 mm, roséguld",
 seo_title="Yogamatta Tunturi 8 mm, roséguld",
 meta="Tunturi yogamatta på 8 mm i TPE, tjockare än vanliga yogamattor (3–4 mm). Halkfri och lätt att rengöra, med bärväska. Finns i 7 färger, här roséguld.",
 intro="Tunturi Yoga Mat 8 mm är en extra tjock matta i TPE för yoga, fitness och pilates. Den är halkfri, lätt att rengöra och levereras med bärväska.",
 passar=["Yoga där du utför många poser liggande eller sittande, till exempel yin yoga, yoga nidra och meditation","Fitness och pilates","Dig som vill ha en tjockare matta än vanliga yogamattor (3–4 mm)"],
 spec=["Tjocklek: 8 mm","Material: TPE (kombination av gummi och plast)","Egenskaper: halkfri, lätt att rengöra med lite rengöringsmedel","Levereras med: bärväska","Färg: roséguld, finns i 7 färger","Vikt: 950 g"],
 faq=[("Hur rengör jag mattan?","Rengör mattan med lite rengöringsmedel."),("Vad ska jag göra när mattan är ny?","Ta ut den ur förpackningen, rulla ut den på golvet och låt den vila i några timmar.")], marke=T1922,
 motivering="Fakta ur källan. Hälsopåståenden (\"mindre belastning på leder\", \"(kronisk) smärta\", \"skada\"), miljöpåståenden (\"miljövänlig\", \"100 % biologiskt nedbrytbar\") och superlativ utelämnas.",
 att_bekrafta=["Källan har en tom rad \"Mått.\". Mattans längd och bredd saknas.","Artikelnumret i texten (14TUSYO077) skiljer sig från SKU (14TUSYO079).","Taggen \"På beställning\" tyder på beställningsvara. Standardblocket för beställningsvaror bör användas om det stämmer.","Miljöpåståendet \"100 % biologiskt nedbrytbar\" kräver belägg innan det kan användas."])
